sparql:
SELECT (COUNT(?clinical_trial) AS ?count) FROM <https://omnix.dev/graphs/demo-tenant/kg/clinical-trials>
WHERE {
  ?clinical_trial a <https://omnix.dev/types/ClinicalTrial> .
  ?clinical_trial <https://omnix.dev/types/ClinicalTrial/attrs/conditions> ?condition .
  FILTER (CONTAINS(?condition, "Breast Cancer"))
}

SELECT (AVG(?attendees) AS ?average_attendees)
FROM <https://omnix.dev/graphs/demo-tenant/kg/events-sf>
WHERE {
  {
    SELECT ?host_org
    WHERE {
      ?event <https://omnix.dev/onto/host> ?host_org .
    }
    GROUP BY ?host_org
    HAVING (COUNT(?event) > 5)
  }
  ?event <https://omnix.dev/onto/host> ?host_org .
  ?event <https://omnix.dev/types/Event/attrs/tech_topics> ?tech_topics .
  FILTER(CONTAINS(?tech_topics, "ai")) .
  ?event <https://omnix.dev/types/Event/attrs/attendees> ?attendees .
}

SELECT DISTINCT ?categoryName WHERE {
  ?event a <https://omnix.dev/types/Event> ;
         <https://omnix.dev/types/Event/attrs/host> ?host ;
         <https://omnix.dev/types/Event/attrs/event_category> ?categoryName .
  ?host <https://omnix.dev/types/Organization/attrs/name> ?hostName .
  FILTER (CONTAINS(LCASE(?hostName), LCASE('the ai collective')))
}

SELECT ((?count_exp / ?count_keller) AS ?ratio)

FROM <https://omnix.dev/graphs/demo-tenant/kg/zillow-austin>
WHERE {
  {
    SELECT (COUNT(DISTINCT ?listing) AS ?count_exp)
    WHERE {
      ?listing a <https://omnix.dev/types/PropertyListing> .
      ?listing <https://omnix.dev/onto/broker> ?broker_exp .
      ?broker_exp <https://omnix.dev/types/Broker/attrs/name> ?broker_exp_name .
      FILTER(CONTAINS(LCASE(?broker_exp_name), LCASE("eXp Realty, LLC")))
      ?listing <https://omnix.dev/onto/city> ?city .
      ?city <https://omnix.dev/types/City/attrs/name> ?city_name .
      FILTER(CONTAINS(LCASE(?city_name), LCASE("Austin")))
    }
  }
  {
    SELECT (COUNT(DISTINCT ?listing) AS ?count_keller)
    WHERE {
      ?listing a <https://omnix.dev/types/PropertyListing> .
      ?listing <https://omnix.dev/onto/broker> ?broker_keller .
      ?broker_keller <https://omnix.dev/types/Broker/attrs/name> ?broker_keller_name .
      FILTER(CONTAINS(LCASE(?broker_keller_name), LCASE("Keller Williams Realty")))
      ?listing <https://omnix.dev/onto/city> ?city .
      ?city <https://omnix.dev/types/City/attrs/name> ?city_name .
      FILTER(CONTAINS(LCASE(?city_name), LCASE("Austin")))
    }
  }
}

SELECT (xsd:decimal(?paidCount) / ?totalCount * 100 AS ?percentage_not_free)

FROM <https://omnix.dev/graphs/demo-tenant/kg/events-sf>
WHERE {
    {
        SELECT (COUNT(DISTINCT ?event) AS ?totalCount)
        WHERE {
            ?event a <https://omnix.dev/types/Event> .
            ?event <https://omnix.dev/onto/event_category> ?category .
            ?category <https://omnix.dev/types/EventCategory/attrs/name> "Business & Entrepreneurship" .
        }
    }
    {
        SELECT (COUNT(DISTINCT ?event) AS ?paidCount)
        WHERE {
            ?event a <https://omnix.dev/types/Event> .
            ?event <https://omnix.dev/onto/event_category> ?category .
            ?category <https://omnix.dev/types/EventCategory/attrs/name> "Business & Entrepreneurship" .
            ?event <https://omnix.dev/types/Event/attrs/is_free> false .
        }
    }
}

SELECT (SUM(?bedrooms) AS ?totalBedrooms)  FROM <https://omnix.dev/graphs/demo-tenant/kg/zillow-austin>
WHERE {
  {
    SELECT ?broker ?brokerName (COUNT(?listing) AS ?listingCount) WHERE {
      ?listing <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://omnix.dev/types/PropertyListing> .
      ?listing <https://omnix.dev/onto/broker> ?broker .
      ?broker <https://omnix.dev/types/Broker/attrs/name> ?brokerName .
    }
    GROUP BY ?broker ?brokerName
    ORDER BY DESC(?listingCount)
    LIMIT 3
  }
  ?listing <https://omnix.dev/onto/broker> ?broker .
  ?listing <https://omnix.dev/types/PropertyListing/attrs/bedrooms> ?bedrooms .
}
